def grade_imported_diagnoses(apps, schema_editor):
    """EDCS recorded every diagnosis as confirmed. Keep it confirmed only with a supporting test (echo for cardiac,
    HbA1c or glucose for diabetes, a confirmatory test or genotype for sickle cell); otherwise it is suspected.
    The same rule as integrations.edcs.grade_imported_diagnoses, written out here so the migration stays fixed."""
    Diagnosis = apps.get_model('clinical', 'Diagnosis')
    LabOrder = apps.get_model('laboratory', 'LabOrder')
    InvestigationOrder = apps.get_model('investigations', 'InvestigationOrder')
    diagnoses = Diagnosis.objects.filter(created_by__username='edcs_import', status='confirmed',
                                         disease__code__in=['cardiac', 'diabetes', 'scd'])
    patients = diagnoses.values('patient_id')
    labs = LabOrder.objects.filter(patient_id__in=patients)
    supported = {(p, 'diabetes') for p in labs.filter(test__code__in=['hba1c', 'fbg', 'rbg']).values_list('patient_id', flat=True)}
    supported |= {(p, 'scd') for p in labs.filter(test__code__in=['scd-confirm', 'hb-electro']).values_list('patient_id', flat=True)}
    for patient_id, value in labs.filter(test__code='scd-result').values_list('patient_id', 'result_value'):
        value = (value or '').lower()
        if value in ('ss', 'sa', 'sbthal', 'sc') or 'elec' in value:
            supported.add((patient_id, 'scd'))
    echo = InvestigationOrder.objects.filter(patient_id__in=patients).filter(
        Q(modality='echo') | Q(investigation_type__code='echo'))
    supported |= {(p, 'cardiac') for p in echo.values_list('patient_id', flat=True)}
    unsupported = [pk for pk, patient_id, code in diagnoses.values_list('pk', 'patient_id', 'disease__code')
                   if (patient_id, code) not in supported]
    Diagnosis.objects.filter(pk__in=unsupported).update(status='provisional')


